#!/usr/bin/env python3
"""Builds the Orchestrator-level tables of SCI45 package P1 from statements that are in the verified tables (output/, verify/). Re-run after any correction."""
import csv, pathlib
HERE = pathlib.Path(__file__).resolve().parent
OUT = HERE / "output"
def w(name, header, rows):
    for r in rows: assert len(r) == len(header), (name, r[0], len(r), len(header))
    with open(OUT / name, "w", newline="") as fh:
        c = csv.writer(fh, delimiter="\t", lineterminator="\n"); c.writerow(header); c.writerows(rows)

